# This code has been fully generated by an AI.
"""Soundboard-Bibliothek: Der Ordner ``memes/`` ist die Quelle, ein Index merkt sich Namen und Reihenfolge.

Dateien, die jemand in den Ordner legt, erscheinen von selbst; hochgeladene landen dort auch.
Videos mit Haken „Green Screen entfernen“ stellt ein eigener Prozess frei (``memes.process_file``).
"""

import json
import logging
import multiprocessing
import queue
import re
import shutil
import threading
import time
from collections.abc import Callable
from pathlib import Path

from .memes import has_alpha

log = logging.getLogger(__name__)

MIME = {
    ".mp4": "video/mp4", ".m4v": "video/mp4", ".mov": "video/mp4", ".webm": "video/webm",
    ".mkv": "video/webm", ".ogv": "video/ogg", ".mp3": "audio/mpeg", ".wav": "audio/wav", ".ogg": "audio/ogg",
    ".oga": "audio/ogg",
    ".m4a": "audio/mp4", ".aac": "audio/aac", ".flac": "audio/flac", ".opus": "audio/ogg",
    ".gif": "image/gif", ".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg",
    ".webp": "image/webp",
}
EXT = {"video/mp4": ".mp4", "video/webm": ".webm", "video/ogg": ".ogv", "video/quicktime": ".mov",
       "audio/mpeg": ".mp3", "audio/wav": ".wav", "audio/x-wav": ".wav", "audio/ogg": ".ogg",
       "audio/mp4": ".m4a", "audio/aac": ".aac", "audio/flac": ".flac", "image/gif": ".gif",
       "image/png": ".png", "image/jpeg": ".jpg", "image/webp": ".webp"}
POLL_S = 2.0
# So lange darf eine verschwundene Datei durch eine gleichnamige mit anderer Endung ersetzt werden
# (Skript macht aus X.mp4 ein X.webm); Name und Platz im Soundboard bleiben dann erhalten.
CARRY_S = 120.0
# Taucht eine Datei auf, deren Name schon im Soundboard steht, erst kurz warten: meist wird gerade ersetzt.
SAME_STEM_POLLS = 5


def display_name(file: str) -> str:
    return Path(file).stem.replace("_", " ").strip() or file


def _safe_stem(name: str) -> str:
    stem = re.sub(r'[<>:"/\\|?*\x00-\x1f]', "_", name).strip(" .")
    return stem[:80] or "Meme"


def _key_job(src: str, progress, pipe) -> None:
    """Läuft im eigenen Prozess, damit das Kodieren weder GIL noch Tracking blockiert."""
    from .memes import KeyingError, low_priority, process_file

    low_priority()

    def report(done: float) -> None:
        progress.value = done

    try:
        out = process_file(Path(src), threads=2, progress=report)
        pipe.send(("ok", out.name) if out else ("none", ""))
    except KeyingError as exc:
        pipe.send(("error", str(exc)))
    except Exception as exc:
        pipe.send(("error", str(exc) or type(exc).__name__))


class MemeLibrary:
    def __init__(self, folder: Path, index: Path, on_change: Callable[[str | None], None] = lambda _: None,
                 legacy: Path | None = None, watch: bool = True):
        self.folder, self.index_file, self.on_change = folder, index, on_change
        folder.mkdir(parents=True, exist_ok=True)
        index.parent.mkdir(parents=True, exist_ok=True)
        self.lock = threading.RLock()
        self.entries: list[dict] = json.loads(index.read_text("utf-8")) if index.exists() else []
        self.keying: dict[str, float] = {}
        self._pending: dict[str, tuple[tuple[int, int], int]] = {}
        self._gone: dict[str, tuple[dict, int, float]] = {}
        # Unter Windows lassen sich gerade ausgelieferte Dateien nicht löschen; später nochmal versuchen.
        self._doomed: set[str] = set()
        self._jobs: queue.Queue[str] = queue.Queue()
        if legacy is not None:
            self._migrate(legacy)
        self.scan(settle=False)
        threading.Thread(target=self._keyer, name="keyer", daemon=True).start()
        # Was beim letzten Beenden noch freigestellt wurde, wird jetzt fertig gemacht.
        for entry in self.entries:
            if entry.get("processing"):
                self._jobs.put(entry["file"])
        if watch:
            threading.Thread(target=self._watch, name="memes", daemon=True).start()

    def public(self, entry: dict) -> dict:
        return {"url": self.url(entry["file"]), "name": entry["name"], "mime": entry["mime"],
                "cutout": entry.get("cutout", False), "processing": entry.get("processing", False)}

    @staticmethod
    def url(file: str) -> str:
        from urllib.parse import quote

        return "/memes/" + quote(file)

    def board(self) -> list[dict]:
        with self.lock:
            return [self.public(e) for e in self.entries]

    def path(self, file: str) -> tuple[Path, str] | None:
        """Nur Dateien aus dem Index werden ausgeliefert; so kommt niemand per ../ aus dem Ordner."""
        with self.lock:
            for entry in self.entries:
                if entry["file"] == file:
                    return self.folder / file, entry["mime"]
        return None

    def _entry(self, file: str) -> dict:
        mime = MIME.get(Path(file).suffix.lower(), "application/octet-stream")
        entry = {"file": file, "name": display_name(file), "mime": mime}
        if has_alpha(self.folder / file):
            entry["cutout"] = True
        return entry

    def _listing(self) -> dict[str, tuple[int, int]]:
        found = {}
        for path in self.folder.iterdir():
            if path.name.startswith(".") or path.suffix.lower() not in MIME or not path.is_file():
                continue
            try:
                st = path.stat()
            except OSError:
                continue
            found[path.name] = (st.st_size, st.st_mtime_ns)
        return found

    def scan(self, settle: bool = True) -> None:
        now = time.monotonic()
        # Unter der Sperre lesen: sonst verschwindet ein gleichzeitig hochgeladenes Meme wieder.
        with self.lock:
            found = self._listing()
            changed = False
            for name in list(self._doomed):
                try:
                    (self.folder / name).unlink(missing_ok=True)
                    self._doomed.discard(name)
                except PermissionError:
                    pass
                found.pop(name, None)
            for i in range(len(self.entries) - 1, -1, -1):
                entry = self.entries[i]
                if entry["file"] not in found and not entry.get("processing"):
                    self._gone[Path(entry["file"]).stem.lower()] = (self.entries.pop(i), i, now)
                    log.info("Meme „%s“ aus dem Ordner verschwunden.", entry["file"])
                    changed = True
            known = {e["file"] for e in self.entries}
            stems = {Path(f).stem.lower() for f in known}
            busy = {Path(e["file"]).stem.lower() for e in self.entries if e.get("processing")}
            fresh = []
            for name, sig in found.items():
                if name in known:
                    continue
                stem = Path(name).stem.lower()
                if stem in busy:
                    continue
                if settle:
                    # Erst übernehmen, wenn Größe und Zeitstempel stehen; sonst wird gerade noch kopiert.
                    last, polls = self._pending.get(name, (None, 0))
                    polls = polls + 1 if last == sig else 0
                    self._pending[name] = (sig, polls)
                    if polls < 1 or (stem in stems and polls < SAME_STEM_POLLS):
                        continue
                self._pending.pop(name, None)
                fresh.append(name)
            # Rückwärts einfügen, weil neue Kacheln vorne stehen; so bleibt Meme 001 oben.
            for name in sorted(fresh, reverse=True):
                entry = self._entry(name)
                old = self._gone.pop(Path(name).stem.lower(), None)
                if old:
                    entry["name"] = old[0]["name"]
                    self.entries.insert(min(old[1], len(self.entries)), entry)
                    log.info("Meme „%s“ ersetzt durch %s.", old[0]["file"], name)
                else:
                    self.entries.insert(0, entry)
                    log.info("Meme „%s“ im Ordner gefunden.", name)
                changed = True
            self._pending = {k: v for k, v in self._pending.items() if k in found}
            self._gone = {k: v for k, v in self._gone.items() if now - v[2] < CARRY_S}
            if changed:
                self._save()
        if changed:
            self.on_change(None)

    def _watch(self) -> None:
        while self.folder.is_dir():
            time.sleep(POLL_S)
            try:
                self.scan()
            except Exception:
                log.exception("Meme-Ordner konnte nicht gelesen werden.")

    def _unique(self, stem: str, ext: str) -> str:
        taken = {p.stem.lower() for p in self.folder.iterdir()}
        taken |= {Path(e["file"]).stem.lower() for e in self.entries}
        base, n = stem, 2
        while stem.lower() in taken or f".{stem}.keying".lower() in taken:
            stem, n = f"{base} ({n})", n + 1
        return stem + ext

    def add(self, body: bytes, mime: str, name: str, key: bool = False) -> dict:
        ext = EXT.get(mime) or Path(name).suffix.lower() or ".bin"
        name = name.strip() or "Meme"
        with self.lock:
            file = self._unique(_safe_stem(name), ext)
            tmp = self.folder / f".{file}.upload"
            tmp.write_bytes(body)
            tmp.replace(self.folder / file)
            entry = self._entry(file)
            entry["name"] = name
            if key and entry["mime"].startswith("video/") and not entry.get("cutout"):
                entry["processing"] = True
                self.keying[self.url(file)] = 0.0
            self.entries.insert(0, entry)
            self._save()
        log.info("Meme „%s“ hochgeladen als %s%s.", name, file, " (wird freigestellt)" if key else "")
        if entry.get("processing"):
            self._jobs.put(file)
        self.on_change(None)
        return entry

    def rename(self, file: str, name: str) -> bool:
        with self.lock:
            for entry in self.entries:
                if entry["file"] == file:
                    entry["name"] = name
                    self._save()
                    break
            else:
                return False
        self.on_change(None)
        return True

    def remove(self, file: str) -> bool:
        with self.lock:
            entry = next((e for e in self.entries if e["file"] == file), None)
            if entry is None or entry.get("processing"):
                return False
            self.entries.remove(entry)
            try:
                (self.folder / file).unlink(missing_ok=True)
            except PermissionError:
                self._doomed.add(file)
            self._save()
        log.info("Meme „%s“ gelöscht.", file)
        self.on_change(None)
        return True

    def _keyer(self) -> None:
        # spawn statt fork: auch unter Linux kein Kopieren von Kamera-Threads und offenen Sockets.
        ctx = multiprocessing.get_context("spawn")
        while True:
            file = self._jobs.get()
            progress = ctx.Value("d", 0.0)
            recv, send = ctx.Pipe(duplex=False)
            log.info("Meme %s wird freigestellt …", file)
            proc = ctx.Process(target=_key_job, args=(str(self.folder / file), progress, send), daemon=True)
            proc.start()
            send.close()
            while proc.is_alive():
                proc.join(0.5)
                if self.keying.get(self.url(file)) != round(progress.value, 2):
                    self.keying[self.url(file)] = round(progress.value, 2)
                    self.on_change(None)
            status, info = recv.recv() if recv.poll() else ("error", f"Prozess beendet ({proc.exitcode})")
            self._finish(file, status, info)

    def _finish(self, file: str, status: str, info: str) -> None:
        with self.lock:
            self.keying.pop(self.url(file), None)
            entry = next((e for e in self.entries if e["file"] == file), None)
            if entry is not None:
                entry.pop("processing", None)
                if status == "ok":
                    entry.update(file=info, mime="video/webm", cutout=True)
            self._save()
        label = entry["name"] if entry else file
        if status == "ok":
            log.info("Meme %s freigestellt: %s", file, info)
            message = None
        elif status == "none":
            log.info("Meme %s: kein Green Screen erkannt, Original bleibt.", file)
            message = f"{label}: kein Green Screen erkannt, Video bleibt unverändert."
        else:
            log.warning("Meme %s konnte nicht freigestellt werden: %s", file, info)
            message = (f"{label}: Green Screen entfernen fehlgeschlagen ({info}). "
                       "Das Original bleibt im Soundboard.")
        self.on_change(message)

    def _migrate(self, legacy: Path) -> None:
        """Einmalig: Soundboard aus data/media/board.json in den Meme-Ordner übernehmen."""
        board = legacy / "board.json"
        if not board.exists():
            return
        old = json.loads(board.read_text("utf-8"))
        stems = {p.stem.lower(): p.name for p in self.folder.iterdir() if not p.name.startswith(".")}
        known = {e["file"] for e in self.entries}
        moved = []
        for item in old:
            source = item.get("source")
            file = stems.get(Path(source).stem.lower()) if source else None
            if file is None and (legacy / item["key"]).is_file():
                ext = EXT.get(item["mime"], ".bin")
                file = self._unique(_safe_stem(item["name"]), ext)
                shutil.move(legacy / item["key"], self.folder / file)
                stems[Path(file).stem.lower()] = file
            if file and file not in known:
                entry = self._entry(file)
                entry["name"] = item["name"]
                moved.append(entry)
                known.add(file)
        self.entries = moved + self.entries
        self._save()
        board.unlink()
        log.info("%d Soundboard-Kacheln aus %s in den Meme-Ordner übernommen.", len(moved), legacy)

    def _save(self) -> None:
        tmp = self.index_file.with_suffix(".tmp")
        tmp.write_text(json.dumps(self.entries, ensure_ascii=False, indent=1), "utf-8")
        tmp.replace(self.index_file)
